pub struct Snapshot64 { pub format:String,pub roots:super::super::HierarchicalSpannIds,pub generation:u64,pub dim:usize,pub metric:DistanceFunction,pub config:HierarchicalSpannConfig,pub max_leaf_rows:usize,pub metadata_roots:Option<BTreeMap<u32,uuid::Uuid>>,pub owner_slots:usize }
/// A fixed per-worker window bounds deltas independently of logical balance cuts.
#[derive(Clone,Copy,Debug,serde::Serialize,serde::Deserialize)]
pub struct StableInsertPolicy{pub rows:usize,pub worker_bytes:usize}
impl StableInsertPolicy{
    pub(crate) fn model_bytes(rows:usize,dim:usize,code:usize)->Result<usize>{rows.checked_mul(dim.checked_mul(8).and_then(|v|v.checked_add(code.checked_mul(3)?)).and_then(|v|v.checked_add(256)).ok_or_else(||anyhow::anyhow!("stable worker row extent"))?).and_then(|v|v.checked_add(65536)).ok_or_else(||anyhow::anyhow!("stable worker extent"))}
    pub(crate) fn validate(&self,dim:usize)->Result<()>{ensure!(self.rows>0&&self.rows<=64&&Self::model_bytes(self.rows,dim,Code::<1>::size(dim))?<=self.worker_bytes,"stable window/byte policy");Ok(())}
}
/// Exclusive public phase methods exclude mutation during placement/publication.
