        if self.saved_metadata.is_some(){for chunk in scored.chunks_mut(16){let ids:Vec<_>=chunk.iter().map(|v|super::super::partition_authority::VectorId64(v.0)).collect();let records=self.saved_metadata.as_mut().unwrap().records(&ids)?.into_iter().map(|v|v.ok_or_else(||anyhow::anyhow!("saved rerank metadata missing"))).collect::<Result<Vec<_>>>()?;let vectors=self.record_vectors(&records)?;for((_,score),vector)in chunk.iter_mut().zip(vectors){*score=self.snapshot.metric.distance(query,&vector);ensure!(score.is_finite(),"saved exact score finite");}}}
        else{for(id,score) in &mut scored{let vector=self.vectors.get(&vector_prefix(*id),*id as u32).await.map_err(|e|anyhow::anyhow!("{e}"))?.ok_or_else(||anyhow::anyhow!("missing pinned embedding"))?;ensure!(vector.len()==self.snapshot.dim,"pinned embedding shape");*score=self.snapshot.metric.distance(query,vector);ensure!(score.is_finite(),"exact score finite");}}scored.sort_unstable_by(|a,b|a.1.partial_cmp(&b.1).unwrap());scored.truncate(k);self.vectors.clear_loaded_blocks();
