    async fn census_paged(&mut self)->Result<BTreeMap<u64,(u8,Vec<u8>,Vec<u32>)>>{let mut result=BTreeMap::new();for leaf in self.audit_leaves()?{let posting=self.live_posting(leaf).await?;for start in (0..posting.ids.len()).step_by(16){let end=posting.ids.len().min(start+16);let ids:Vec<_>=posting.ids[start..end].iter().map(|id|super::super::partition_authority::VectorId64(*id)).collect();let records=self.saved_metadata.as_mut().unwrap().records(&ids)?.into_iter().map(|v|v.ok_or_else(||anyhow::anyhow!("saved census metadata missing"))).collect::<Result<Vec<_>>>()?;let vectors=self.record_vectors(&records)?;for(offset,(record,vector))in records.into_iter().zip(vectors).enumerate(){let i=start+offset;if record.version&DELETED_BIT!=0||record.version!=posting.versions[i]{continue;}let code=code_slice(&posting.codes,i,Code::<1>::size(self.snapshot.dim)).to_vec();ensure!(result.insert(posting.ids[i],(record.version,code,vector.iter().map(|v|v.to_bits()).collect())).is_none(),"duplicate saved current membership");}}self.posting.clear_loaded_blocks();}Ok(result)}
