        assert_eq!(writer.backend().current(0),Some(2));assert!(!writer.kernel.test_register_reassignment(0,1,0,&rows[0].1));
        writer.kernel.scrub_owner_fixture(0);let saved=writer.save(&p).await.unwrap();let mut current=Reader64::open(&p,saved,128).await.unwrap();let census=current.census().await.unwrap();assert_eq!(census.len(),rows.len());for(id,v)in &rows{assert_eq!(census[id].2,v.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}assert_eq!(old.census().await.unwrap(),before);
        assert!(writer.kernel.nodes.is_empty()&&writer.backend().leaf_owner.is_empty());println!("LOCAL_REASSIGNMENT_CONNECTED {}",writer.diagnostic_report());
