    #[tokio::test(flavor="multi_thread",worker_threads=2)]
    async fn local_reassignment_atomic_final_slot_and_collision(){
        let dir=tempfile::tempdir().unwrap();let p=provider(dir.path());let mut writer=WideOwnerWriter::new(32,DistanceFunction::Euclidean,config(),1,&[0],128,p.clone(),super::super::super::owner_vector_store::VectorLimits::default()).unwrap();writer.enable_dirty_scheduler(p.clone(),super::super::owner_work_queue::Limits::default()).unwrap();writer.enable_full_records(p,super::super::super::owner_node_access::Limits::default()).unwrap();writer.set_single_owner_local_reassignment(true).unwrap();writer.add_phase(&[(0,vec![0.;32]),(64,vec![1.;32])],2).unwrap();let b=writer.backend();
        b.actor(0).call(|s|{let mut leaf=super::clone_leaf(s.leaves.get(&0).unwrap());leaf.ids.clear();leaf.versions.clear();leaf.codes.clear();leaf.length=0;s.leaves.insert(1,leaf);});b.physical_capacity.store(3,Ordering::Relaxed);
        let barrier=std::sync::Barrier::new(2);let results=std::thread::scope(|scope|{let a=scope.spawn(||{barrier.wait();b.reassign_local(0,0,1,&[0.;32],&[0.;32])});let c=scope.spawn(||{barrier.wait();b.reassign_local(1,64,1,&[1.;32],&[0.;32])});vec![a.join().unwrap(),c.join().unwrap()]});assert_eq!(results.iter().filter(|v|v.is_ok()).count(),1);assert_eq!(results.iter().filter(|v|v.is_err()).count(),1);assert_eq!(b.actor(0).call(|s|s.physical),3);let versions=[b.current(0).unwrap(),b.current(64).unwrap()];assert!(versions==[1,2]||versions==[2,1]);assert_eq!(b.actor(0).call(|s|s.leaves.values().flat_map(|leaf|leaf.ids.iter().zip(&leaf.versions)).filter(|(id,v)|s.current.read().get(id)==Some(v)).count()),2);b.physical_capacity.store(512,Ordering::Relaxed);
        std::thread::scope(|scope|{for ids in [[0u64,64],[64,0]]{scope.spawn(move||{for _ in 0..8{for id in ids{let expected=b.current(id).unwrap();b.reassign_local(0,id,expected,&[id as f32;32],&[0.;32]).unwrap();}}});}});
        println!("LOCAL_FINAL_SLOT versions={versions:?} physical=3; opposite-order colliding identity requests progress; {}",b.local_reassignment_observation());
    }
