    async fn paged_metadata_competing_reassignments_final_physical_slot(){
        let dir=tempfile::tempdir().unwrap();let p=provider(dir.path());let mut writer=WideOwnerWriter::new(32,DistanceFunction::Euclidean,config(),2,&[0],256,p.clone(),super::super::super::owner_vector_store::VectorLimits::default()).unwrap();writer.enable_dirty_scheduler(p.clone(),super::super::owner_work_queue::Limits::default()).unwrap();writer.enable_full_records(p.clone(),super::super::super::owner_node_access::Limits::default()).unwrap();writer.set_stable_insertion(Some(StableInsertPolicy{rows:64,worker_bytes:1048576})).unwrap();writer.enable_paged_metadata(p.clone(),super::super::super::owner_vector_metadata::Limits::default()).unwrap();let input:Vec<_>=(0..64u64).map(|id|(id,(0..32).map(|d|id as f32*10.+d as f32/32.).collect::<Vec<_>>())).collect();writer.add_phase(&input,4).unwrap();writer.balance_phase(4).unwrap();let b=writer.backend().clone();let mut leaves=b.actors[0].call(|s|s.leaves.iter().filter(|(_,leaf)|!leaf.ids.is_empty()).map(|(id,_)|*id).collect::<Vec<_>>());leaves.sort_unstable();assert!(leaves.len()>=4);let targets=[leaves[0],leaves[1]];for target in targets{assert!(writer.move_leaf(target,1).unwrap()>0);}let ids:Vec<_>=input.iter().filter(|(id,_)|b.resolve_vector(*id).unwrap().0==0).take(2).map(|v|v.0).collect();assert_eq!(ids.len(),2);let versions=[b.current(ids[0]).unwrap(),b.current(ids[1]).unwrap()];let before=b.actors[1].call(|s|s.physical);b.physical_capacity.store(before+1,Ordering::Relaxed);let saved=writer.save(&p).await.unwrap();let mut old=Reader64::open(&p,saved,512).await.unwrap();let old_census=old.census().await.unwrap();let(entered,waiting)=std::sync::mpsc::channel();let(resume,resuming)=std::sync::mpsc::channel();*b.transfer_pause.lock()=Some((entered,resuming));std::thread::scope(|scope|{let kernel=&writer.kernel;let first=scope.spawn(||kernel.test_register_reassignment(ids[0],versions[0],targets[0],&input[ids[0]as usize].1));waiting.recv_timeout(std::time::Duration::from_secs(5)).unwrap();let(start,start_rx)=std::sync::mpsc::channel();let(done,done_rx)=std::sync::mpsc::channel();let ids=&ids;let input=&input;let second=scope.spawn(move||{start.send(()).unwrap();let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||kernel.test_register_reassignment(ids[1],versions[1],targets[1],&input[ids[1]as usize].1)));done.send(result.is_err()).unwrap();});start_rx.recv().unwrap();assert!(done_rx.recv_timeout(std::time::Duration::from_millis(30)).is_err(),"second transfer waits for the global structural scope");resume.send(()).unwrap();assert!(first.join().unwrap());assert!(done_rx.recv_timeout(std::time::Duration::from_secs(5)).unwrap(),"capacity rejection occurs before second version change");second.join().unwrap();});assert_eq!(b.actors[1].call(|s|s.physical),before+1);assert_eq!(b.current(ids[0]),Some(versions[0]+1));assert_eq!(b.current(ids[1]),Some(versions[1]));assert_eq!(b.resolve_vector(ids[1]).unwrap().0,0);assert_eq!(old.census().await.unwrap(),old_census);println!("PAGED_FINAL_SLOT physical_before={} physical_after={} admitted=1 rejected=1",before,b.actors[1].call(|s|s.physical));
    }

