            assert_eq!(registration_calls,if buffered{3}else{129});assert_eq!(writer.backend().registration_node_leases.load(Ordering::Relaxed),if buffered{3}else{129});if buffered{assert_eq!(observation["flush_length_histogram"][64],2);assert_eq!(observation["flush_length_histogram"][1],1);assert_eq!(observation["registered_rows"],129);assert_eq!(writer.backend().authority.registration_observation()["reserve_home_messages"],4);}
