            let before=writer.backend().actor_work.calls.load(Ordering::Relaxed);let leases=writer.backend().registration_node_leases.load(Ordering::Relaxed);writer.add_phase(&added,1).unwrap();let calls=writer.backend().actor_work.calls.load(Ordering::Relaxed)-before;let leases=writer.backend().registration_node_leases.load(Ordering::Relaxed)-leases;assert_eq!(calls,64);assert_eq!(leases,64);
