    #[tokio::test(flavor="multi_thread",worker_threads=2)]
    async fn stable_buffered_failure_caps_and_partial_phase_poison(){
        for partial in [false,true]{let dir=tempfile::tempdir().unwrap();let p=provider(dir.path());let mut writer=WideOwnerWriter::new(32,DistanceFunction::Euclidean,config(),2,&[0],512,p.clone(),super::super::super::owner_vector_store::VectorLimits::default()).unwrap();writer.enable_dirty_scheduler(p.clone(),super::super::owner_work_queue::Limits::default()).unwrap();writer.enable_full_records(p.clone(),super::super::super::owner_node_access::Limits::default()).unwrap();
            writer.add_phase(&[(0,vec![0.;32])],1).unwrap();let first=writer.save(&p).await.unwrap();let mut old=Reader64::open(&p,first,128).await.unwrap();let before=old.census().await.unwrap();
            assert!(writer.set_stable_insertion(Some(StableInsertPolicy{rows:65,worker_bytes:1024*1024})).is_err());assert!(writer.set_stable_insertion(Some(StableInsertPolicy{rows:64,worker_bytes:1})).is_err());writer.set_stable_insertion(Some(StableInsertPolicy{rows:64,worker_bytes:1024*1024})).unwrap();
            assert!(writer.add_phase(&[(0,vec![0.;32])],1).is_err());assert!(!writer.failed);assert!(writer.add_phase(&[((9u64<<32)|1,vec![0.;32])],1).is_err());assert!(!writer.failed);
            if partial{writer.backend().stable_fail_at.store(2,Ordering::Relaxed);}else{writer.set_diagnostic_capacity(64,false).unwrap();}
            let rows:Vec<_>=(1..130u64).map(|id|(id,vec![id as f32;32])).collect();assert!(writer.add_phase(&rows,1).is_err());assert!(writer.failed);assert!(writer.save(&p).await.is_err());assert!(writer.add_phase(&[(200,vec![0.;32])],1).is_err());assert_eq!(old.census().await.unwrap(),before);
            let current=writer.backend().actors[0].call(|state|state.current.read().len());assert_eq!(current,if partial{65}else{1});for(id,_)in &rows[64..]{assert!(writer.backend().current(*id).is_none());}assert_eq!(writer.backend().authority.remaining(0),512-current);
            println!("STABLE_FAILURE {}",serde_json::json!({"partial":partial,"current_rows":current,"old_rows":before.len(),"stable":writer.backend().stable_observation()}));
        }
    }

