    async fn full_record_predicate_sequence(prefix:bool,local_cleanup:bool,decoded_cache:bool,local_transaction:bool) {
        let dir=tempfile::tempdir().unwrap();let p=provider(dir.path());let mut c=config();c.split_threshold=8;
        let input:Vec<_>=(0..32u64).map(|id|(id,(0..32).map(|d|if d==0{(id/4)as f32*10.}else{(id%4)as f32+d as f32/32.}).collect::<Vec<_>>())).collect();
        let mut writer=WideOwnerWriter::new(32,DistanceFunction::Euclidean,c,if local_cleanup{1}else{2},&[0],128,p.clone(),super::super::super::owner_vector_store::VectorLimits{decoded_vector_cache:decoded_cache.then_some(super::super::super::owner_vector_store::DecodedVectorCachePolicy{payload_bytes_per_owner:8192,aggregate_payload_bytes:8192}),split_rows:64,..Default::default()}).unwrap();
        writer.enable_dirty_scheduler(p.clone(),super::super::owner_work_queue::Limits{cache_pages_per_home:1,max_active_pages:128}).unwrap();
        writer.enable_full_records(p.clone(),super::super::super::owner_node_access::Limits::default()).unwrap();
        if local_transaction{writer.set_single_owner_local_reassignment(true).unwrap();}
        if prefix{writer.set_immutable_handle_batching(false).unwrap();writer.set_owner_eligibility_prefix(true).unwrap();}
        if local_cleanup{writer.set_immutable_handle_batching(false).unwrap();writer.set_single_owner_local_scrub(true).unwrap();assert!(writer.set_owner_eligibility_prefix(false).is_ok());assert!(writer.move_leaf(0,1).is_err());}
        writer.add_phase(&input,4).unwrap();if !local_cleanup{assert_eq!(writer.move_leaf(0,1).unwrap(),32);}
        let first=writer.save(&p).await.unwrap();let mut old=Reader64::open(&p,first,128).await.unwrap();let before=old.census().await.unwrap();
        let (execution_owner,leaf)=writer.backend().snapshot_with_owner(0).unwrap();assert_eq!(execution_owner,if local_cleanup{0}else{1});
        let predicate=writer.backend().prepare_predicate(execution_owner,DistanceFunction::Euclidean,&leaf.centroid,&leaf.centroid,&vec![0.;32],&vec![1.;32]);
        let values:Vec<_>=input.iter().map(|(_,v)|Some(Arc::<[f32]>::from(v.clone()))).collect();
        let expected=writer.backend().predicate_batch(0,values.clone(),predicate.clone(),false).unwrap();
        if local_transaction{assert!(writer.kernel.test_register_reassignment(0,1,0,&input[0].1));}
        writer.balance_phase(4).unwrap();if local_transaction{assert!(writer.backend().local_reassignment_calls.load(Ordering::Relaxed)>0,"actual NPA reassignment transactions");}
        assert!(writer.backend().located_owner(0).is_none(),"split retires authoritative source locator");
        assert_eq!(writer.backend().predicate_batch(0,values,predicate.clone(),false).unwrap(),expected);
        for ((_,v),expected)in input.iter().zip(expected){assert_eq!(Some(writer.backend().fp_predicate(0,Arc::from(v.clone()),predicate.clone())),expected);}
        assert!(writer.kernel.nodes.is_empty()&&writer.backend().leaf_owner.is_empty());
        let saved=writer.save(&p).await.unwrap();let mut current=Reader64::open(&p,saved,128).await.unwrap();let census=current.census().await.unwrap();assert_eq!(census.len(),32);
        for(id,v)in &input{assert_eq!(census[id].2,v.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}
        assert_eq!(old.census().await.unwrap(),before);assert!(writer.kernel.stats.splits.load(Ordering::Relaxed)>0);
        if decoded_cache{let report=writer.diagnostic_report();assert_eq!(report["vector_store"]["decoded_vector_cache_admission"]["rows_per_owner"],64);assert!(report["vector_store"]["cache_hits"].as_u64().unwrap()>0);println!("DECODED_CACHE_CONNECTED {}",report);}
        if local_cleanup{let report=writer.diagnostic_report();assert_eq!(report["cleanup"]["effective_local"],true);assert!(report["cleanup"]["local_rows"].as_u64().unwrap()>0);assert_eq!(report["cleanup"]["legacy_validation_rows"],0);assert_eq!(report["owner_eligibility_prefix"]["enabled"],false);assert_eq!(report["immutable_handle_resolution_mode"],"owner-scalar");println!("SINGLE_OWNER_CLEANUP_CONNECTED {}",report);}
        if prefix {let report=writer.diagnostic_report();assert_eq!(report["immutable_handle_batching"],false);assert_eq!(report["owner_eligibility_prefix"]["enabled"],true);assert!(report["owner_eligibility_prefix"]["consumed_rows"].as_u64().unwrap()>0);let beam=ReadBeamPolicy::uniform(Some(2.),128,128);let query=&input[0].1;for r in [&mut old,&mut current]{let hits=r.query(query,32,128,&beam).await.unwrap();assert_eq!(hits.results.len(),32);for(id,distance)in hits.results{assert_eq!(distance.to_bits(),DistanceFunction::Euclidean.distance(query,&input[id as usize].1).to_bits());}}println!("FULL_RECORD_ELIGIBILITY {}",report);}
        println!("PREDICATE_RETIRED_SOURCE {}",serde_json::json!({"execution_owner":execution_owner,"source_locator_absent":true,"current_rows":census.len(),"old_rows":before.len()}));
    }

