        writer.balance_phase(4).unwrap();assert_eq!(writer.kernel.owner_work.as_ref().unwrap().pending(),0);assert_eq!(writer.kernel.nodes.len(),393);let policy=ReadBeamPolicy::uniform(Some(2.0),4,4);let decisions:Vec<_>=input.iter().step_by(128).map(|(_,v)|writer.kernel.navigate_f32(v,&policy)).collect();eprintln!("FULL_STAGE migrate");writer.enable_full_records_with_placement(p.clone(),super::super::super::owner_node_access::Limits{cache_entries:2,cache_bytes:1024,record_bytes:512,pin_bytes:128*1024,dirty_records:128,dirty_bytes:64*1024},super::super::super::owner_placement_catalog::Limits{cache_pages_per_owner:1,active_pages_per_owner:4096,pages_per_phase:16,moves_per_phase:256}).unwrap();assert!(writer.kernel.nodes.is_empty());assert!(writer.backend().leaf_owner.is_empty());for((_,v),expected)in input.iter().step_by(128).zip(decisions){assert_eq!(writer.kernel.navigate_f32(v,&policy),expected);}eprintln!("FULL_STAGE save_old");let first=writer.save(&p).await.unwrap();let mut old=Reader64::open(&p,first,512).await.unwrap();let old_census=old.census().await.unwrap();assert_eq!(old_census.len(),1024);let old_hits=old.query(&input[0].1,4,32,&ReadBeamPolicy::uniform(Some(2.0),4,4)).await.unwrap().results;
